#### Example 3: S3 Object Lock and Retention Configuration (Terraform)

Object lock must be enabled at bucket creation. This Terraform configuration provisions the evidence store bucket with HIPAA (6-year) and FedRAMP (3-year) compliant retention:

```hcl
resource "aws_s3_bucket" "compliance_evidence_store" {
  bucket = "gainwell-compliance-evidence-store-${var.environment}"

  tags = {
    ManagedBy          = "platform-engineering"
    ComplianceScope    = "HIPAA,FedRAMP,SOC2"
    DataClassification = "Controlled"
    RetentionOwner     = "compliance-team"
  }
}

resource "aws_s3_bucket_object_lock_configuration" "evidence_store_lock" {
  bucket = aws_s3_bucket.compliance_evidence_store.id

  rule {
    default_retention {
      mode  = "COMPLIANCE"   # COMPLIANCE mode: cannot be overridden by any IAM principal
      years = 6              # HIPAA minimum: 6 years — covers all compliance scopes
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "evidence_store_lifecycle" {
  bucket = aws_s3_bucket.compliance_evidence_store.id

  rule {
    id     = "transition-to-glacier-after-1-year"
    status = "Enabled"

    transition {
      days          = 365
      storage_class = "GLACIER"
    }

    # Object lock retention is still enforced in Glacier —
    # transition does NOT affect or shorten the lock period.
  }
}

resource "aws_s3_bucket_policy" "evidence_store_policy" {
  bucket = aws_s3_bucket.compliance_evidence_store.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RequireTLSOnly"
        Effect = "Deny"
        Principal = "*"
        Action = "s3:*"
        Resource = [
          "${aws_s3_bucket.compliance_evidence_store.arn}/*",
          aws_s3_bucket.compliance_evidence_store.arn
        ]
        Condition = {
          Bool = { "aws:SecureTransport" = "false" }
        }
      },
      {
        Sid    = "AllowPipelineWrite"
        Effect = "Allow"
        Principal = { AWS = var.pipeline_role_arn }
        Action = ["s3:PutObject", "s3:PutObjectLegalHold"]
        Resource = "${aws_s3_bucket.compliance_evidence_store.arn}/*"
      },
      {
        Sid    = "AllowComplianceTeamRead"
        Effect = "Allow"
        Principal = { AWS = var.compliance_team_role_arn }
        Action = ["s3:GetObject", "s3:ListBucket"]
        Resource = [
          "${aws_s3_bucket.compliance_evidence_store.arn}/*",
          aws_s3_bucket.compliance_evidence_store.arn
        ]
      }
    ]
  })
}
```

**Note:** `COMPLIANCE` mode object lock cannot be shortened or removed by any IAM principal, including account root. Use `GOVERNANCE` mode during development if you need the ability to adjust retention settings.
